import { randomUUID } from "node:crypto";

import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

type Kind = "w9" | "insurance_certificate" | "contract";

const PDF = Buffer.from("%PDF-1.4\n% lif-06 fixture\n");

async function uploadDocument(member: APIRequestContext, vendorId: string, kind: Kind, label: string) {
  const response = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: { name: `${label}.pdf`, mimeType: "application/pdf", buffer: PDF },
    },
  });
  return expectStatus<{ id: string; kind: Kind }>(response, 201);
}

async function waitForExtraction(member: APIRequestContext, documentId: string) {
  await expect
    .poll(
      async () => (await expectStatus<{ status: string }>(await member.get(`/api/documents/${documentId}`), 200)).status,
      { timeout: 60_000 },
    )
    .toBe("extracted");
  return expectStatus<{ id: string; status: string }>(
    await member.get(`/api/documents/${documentId}/extraction`),
    200,
  );
}

async function decide(reviewer: APIRequestContext, extractionId: string, decision: "approve" | "reject") {
  const response = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
    data: { decision, note: null },
  });
  return expectStatus<{ id: string; status: string }>(response, 200);
}

test(
  "approving the replacement approves a vendor whose other documents were already approved",
  { tag: "@LIF-06" },
  async ({ apiAs }) => {
    // Arrange: a vendor with three documents, two of which get approved before the w9 is sent back.
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const vendor = await expectStatus<{ id: string; status: string }>(
      await member.post("/api/vendors", {
        data: {
          name: `LIF06 Vendor ${randomUUID().slice(0, 8)}`,
          category: "services",
          contact_email: `lif06.${randomUUID()}@example.test`,
        },
      }),
      201,
    );

    const originalW9 = await uploadDocument(member, vendor.id, "w9", "w9-original");
    const insurance = await uploadDocument(member, vendor.id, "insurance_certificate", "insurance");
    const contract = await uploadDocument(member, vendor.id, "contract", "contract");

    const originalW9Extraction = await waitForExtraction(member, originalW9.id);
    const insuranceExtraction = await waitForExtraction(member, insurance.id);
    const contractExtraction = await waitForExtraction(member, contract.id);

    await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

    // Approve the insurance and contract; send the original w9 back.
    expect((await decide(reviewer, insuranceExtraction.id, "approve")).status).toBe("approved");
    expect((await decide(reviewer, contractExtraction.id, "approve")).status).toBe("approved");
    expect((await decide(reviewer, originalW9Extraction.id, "reject")).status).toBe("rejected");

    // Resubmit with a replacement w9, which becomes the only pending extraction.
    const replacementW9 = await uploadDocument(member, vendor.id, "w9", "w9-replacement");
    const replacementExtraction = await waitForExtraction(member, replacementW9.id);
    expect(replacementExtraction.status).toBe("pending_review");
    await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

    // Act
    const decision = await decide(reviewer, replacementExtraction.id, "approve");

    // Assert
    expect(decision.status).toBe("approved");

    const updated = await expectStatus<{ status: string }>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
    expect(updated.status).toBe("approved");

    const audit = await expectStatus<{ items: { action: string }[] }>(
      await reviewer.get(`/api/vendors/${vendor.id}/audit`),
      200,
    );
    expect(audit.items.map((event) => event.action)).toContain("vendor.approved");
  },
);
